CREATE TABLE customer_preferences(organization_id uuid NOT NULL,user_id uuid NOT NULL,preferred_location text,preferred_type text,preferred_purpose text CHECK(preferred_purpose IN ('buy','rent')),budget_paise bigint CHECK(budget_paise>=0),bedrooms int CHECK(bedrooms BETWEEN 0 AND 30),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(organization_id,user_id),FOREIGN KEY(organization_id,user_id) REFERENCES users(organization_id,id));
